/// <summary>
/// MET_5012_RebateProcess Load Number sequence for Custom Rebate Transaction number
/// </summary>
[ExtensionOf(classStr(NumberSeqModuleSalesOrder))]
final class METNumberSeqModuleSalesOrder_Extension
{
}

Method.Source:
    /// <summary>
    /// Configures all the data types that are being used by the module.
    /// </summary>
    protected void loadModule()
    {
        
        next loadModule();
        
        NumberSeqDatatype datatype = NumberSeqDatatype::construct();

        datatype.parmDatatypeId(extendedTypeNum(METRebateTransId));
        datatype.parmReferenceHelp(literalStr("@MET:METRebateTransId"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmSortField(100);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);

        this.create(datatype);
        
        datatype.parmDatatypeId(extendedTypeNum(METOrigRebateTransId));
        datatype.parmReferenceHelp(literalStr("@RebatesAndDeductions:UniqueKeyRebateTransIdent"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmSortField(101);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);

        this.create(datatype);

        //MPJ_24809 Returns Claims       

        datatype.parmDatatypeId(extendedTypeNum(METClaimID));
        datatype.parmReferenceHelp(literalStr("@MET:NumberSequenceForReturnClaimId"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardFetchAheadQty(10);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmSortField(102);

        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);

        //CB172_SalesOrderGuides
        //Sales order guide number sequence
        datatype.parmDatatypeId(extendedTypeNum(METSalesOrderGuideId));
        datatype.parmReferenceHelp(literalStr("@MET:SalesOrderGuide"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmSortField(103);
        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);

        this.create(datatype);

        
    }
